import * as React from "react"

function BoimatorDashboard({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="boimator-dashboard"
      className={className}
      {...props}
    >
      <style>{"@keyframes fadeInUp {\n      0% {\n        opacity: 0;\n        transform: translateY(20px);\n      }\n      100% {\n        opacity: 1;\n        transform: translateY(0);\n      }\n    }\n    .fade-in-up {\n      animation: fadeInUp 0.8s ease forwards;\n    }"}</style>
      <div className="max-w-md bg-white bg-opacity-90 rounded-3xl shadow-xl p-8 text-center fade-in-up">
          <h1 className="text-4xl font-extrabold text-purple-700 mb-4">Welcome Back!</h1>
          <p className="text-gray-700 text-lg mb-6">Hope you’re having a fantastic day. Let’s make it even better with some amazing projects ahead!</p>
          <button
            className="bg-purple-700 hover:bg-purple-800 text-white font-semibold py-3 px-8 rounded-full shadow-lg transition"

          >
            Say Hello
          </button>
        </div>
    </div>
  )
}

export { BoimatorDashboard }
